def archiveNotes(count: number): Result<string> {
  // Raise an interrupt with effect `notes::archive` and payload containing the count.
  raise notes::archive("Archive ${count} notes?", { count: count })
  return success("archived ${count}")
}

/**
For count == 11:
- Both handlers run. The inner handler (close to the call) executes and approves the notes::archive interrupt. The outer handler then executes and, because count > 10, rejects the notes::archive interrupt.
- Because any handler rejecting causes the interrupt to be rejected even if an inner handler approved it, archiveNotes ends up failing, so runArchive returns "rejected".
*/
def runArchive(count: number): string {
  handle {
    // Inner handler: approves notes::archive interrupts.
    handle {
      const res: Result<string> = archiveNotes(count)
      if (isSuccess(res)) {
        return "archived"
      }
      return "rejected"
    } with (intr) {
      if (intr.effect == "notes::archive") {
        return approve()
      }
      return pass()
    }
  } with (intr) {
    // Outer handler: rejects notes::archive when count > 10, otherwise passes.
    if (intr.effect == "notes::archive") {
      if (intr.data.count > 10) {
        return reject()
      }
    }
    return pass()
  }
}

